import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import { fitEos, EOS_MIN_POINTS } from "@/core/structure/optimize/eos/fitEos";
import { eosModels, type EosName, type EosParameters } from "@/core/structure/optimize/eos/forms";
import { PressureUnitSystem } from "@/core/units/pressure";

// Generated by ./fixtures/generate_eos_reference.py (ASE 3.26.0, pymatgen
// 2025.6.14, scipy 1.16.0): per dataset, each EOS fitted by ASE
// (EquationOfState), pymatgen (EOS) and a tightly converged scipy
// least_squares ("tight", the true least-squares optimum).
interface Params {
  e0: number;
  v0: number;
  b0: number;
  b1: number;
}
interface Dataset {
  description: string;
  volumes: number[];
  energies: number[];
  truth?: Params & { form: EosName };
  fits?: Record<EosName, { ase: Params; pymatgen: Params & { b0_GPa: number }; tight: Params }>;
  pymatgen_error?: string | null;
  pymatgen_v0?: number | null;
}

const ref = JSON.parse(
  readFileSync(new URL("./fixtures/eos_reference.json", import.meta.url), "utf-8"),
) as Record<string, Dataset>;

const FORMS: EosName[] = ["birchMurnaghan", "murnaghan", "vinet", "poirierTarantola"];
const FITTED = ["synthetic_birchMurnaghan", "synthetic_murnaghan", "synthetic_vinet", "synthetic_poirierTarantola", "Cu_EMT", "Cu_EMT_noisy", "Al_EMT"];

function expectParamsClose(actual: EosParameters, expected: Params, rel: number, e0Abs: number) {
  expect(Math.abs(actual.e0 - expected.e0)).toBeLessThan(e0Abs);
  for (const k of ["v0", "b0", "b1"] as const) {
    expect(Math.abs(actual[k] / expected[k] - 1), k).toBeLessThan(rel);
  }
}

describe("fitEos vs ASE / pymatgen", () => {
  for (const name of FITTED) {
    const data = ref[name];
    for (const form of FORMS) {
      it(`${name}: ${form}`, () => {
        const fit = fitEos(data.volumes, data.energies, { form });
        const expected = data.fits![form];
        // The exact least-squares optimum.
        expectParamsClose(fit, expected.tight, 2e-7, 1e-9);
        // ASE's and pymatgen's (MINPACK, default tolerances ~1.5e-8).
        expectParamsClose(fit, expected.pymatgen, 1e-5, 1e-8);
        expectParamsClose(fit, expected.ase, 5e-5, 1e-7);
        expect(fit.b0GPa / expected.pymatgen.b0_GPa - 1).toBeLessThan(5e-6);
        expect(fit.form).toBe(form);
        expect(fit.warnings).toEqual([]);
      });
    }
  }

  it("recovers the generating parameters of exact synthetic data", () => {
    for (const form of FORMS) {
      const data = ref[`synthetic_${form}`];
      const fit = fitEos(data.volumes, data.energies, { form });
      expectParamsClose(fit, data.truth!, 1e-8, 1e-10);
      expect(fit.rmse).toBeLessThan(1e-10);
      expect(fit.rSquared).toBeCloseTo(1, 12);
    }
  });

  it("reports residuals, fit quality and standard errors for noisy data", () => {
    const data = ref.Cu_EMT_noisy;
    const fit = fitEos(data.volumes, data.energies);
    data.volumes.forEach((v, i) =>
      expect(fit.residuals[i]).toBeCloseTo(data.energies[i] - fit.energy(v), 14),
    );
    const sse = fit.residuals.reduce((a, r) => a + r * r, 0);
    expect(fit.rmse).toBeCloseTo(Math.sqrt(sse / data.volumes.length), 15);
    // Noise was N(0, 1 meV).
    expect(fit.rmse).toBeGreaterThan(2e-4);
    expect(fit.rmse).toBeLessThan(2e-3);
    expect(fit.rSquared).toBeGreaterThan(0.99);
    // The true (noise-free) parameters are within a few standard errors.
    const clean = fitEos(ref.Cu_EMT.volumes, ref.Cu_EMT.energies);
    for (const k of ["e0", "v0", "b0", "b1"] as const) {
      expect(fit.standardErrors[k]).toBeGreaterThan(0);
      expect(Math.abs(fit[k] - clean[k])).toBeLessThan(4 * fit.standardErrors[k]);
    }
  });
});

describe("EOS forms", () => {
  const p: EosParameters = { e0: -3.7, v0: 11.8, b0: 0.85, b1: 4.6 };

  for (const form of FORMS) {
    const model = eosModels[form];

    it(`${form}: E(V0) = E0, P(V0) = 0, P = −dE/dV, B(V0) = B0, B′ = B0′`, () => {
      expect(model.energy(p.v0, p)).toBeCloseTo(p.e0, 13);
      expect(model.pressure(p.v0, p)).toBeCloseTo(0, 13);
      for (const v of [9.5, 11, 12.4, 13.5]) {
        const h = 1e-5;
        const dEdV = (model.energy(v + h, p) - model.energy(v - h, p)) / (2 * h);
        expect(model.pressure(v, p)).toBeCloseTo(-dEdV, 8);
      }
      // B = −V dP/dV at V0, and dB/dP = B0′.
      const h = 1e-4;
      const bulk = (v: number) =>
        (-v * (model.pressure(v + h, p) - model.pressure(v - h, p))) / (2 * h);
      expect(bulk(p.v0)).toBeCloseTo(p.b0, 7);
      const dv = 1e-3;
      const dBdP =
        (bulk(p.v0 - dv) - bulk(p.v0 + dv)) /
        (model.pressure(p.v0 - dv, p) - model.pressure(p.v0 + dv, p));
      expect(dBdP).toBeCloseTo(p.b1, 4);
    });
  }

  it("fit exposes E(V) and P(V) closures", () => {
    const data = ref.Al_EMT;
    const fit = fitEos(data.volumes, data.energies, { form: "vinet" });
    expect(fit.energy(fit.v0)).toBeCloseTo(fit.e0, 13);
    expect(fit.pressure(fit.v0)).toBeCloseTo(0, 13);
    expect(fit.pressure(fit.v0 * 0.95)).toBeGreaterThan(0);
    expect(fit.pressure(fit.v0 * 1.05)).toBeLessThan(0);
  });
});

describe("units", () => {
  it("B0 in GPa uses 1 eV/Å³ = 160.21766208 GPa (ASE / pymatgen)", () => {
    const data = ref.Cu_EMT;
    const fit = fitEos(data.volumes, data.energies);
    expect(fit.b0GPa).toBeCloseTo(fit.b0 * 160.21766208, 10);
    expect(PressureUnitSystem.convert(fit.b0, "eV/Å³", "GPa")).toBeCloseTo(fit.b0GPa, 10);
    expect(PressureUnitSystem.convert(fit.b0GPa, "GPa", "kbar")).toBeCloseTo(fit.b0GPa * 10, 9);
  });

  it("fitting per-atom vs per-cell data gives the same B0", () => {
    const data = ref.Cu_EMT;
    const perCell = fitEos(data.volumes, data.energies);
    const doubled = fitEos(
      data.volumes.map((v) => 2 * v),
      data.energies.map((e) => 2 * e),
    );
    expect(doubled.b0 / perCell.b0 - 1).toBeLessThan(1e-8);
    expect(doubled.v0 / (2 * perCell.v0) - 1).toBeLessThan(1e-8);
    expect(doubled.b1 / perCell.b1 - 1).toBeLessThan(1e-7);
  });
});

describe("fitEos error paths", () => {
  const { volumes, energies } = ref.Cu_EMT;

  it("needs enough distinct points", () => {
    expect(EOS_MIN_POINTS).toBe(5);
    expect(() => fitEos(volumes.slice(0, 4), energies.slice(0, 4))).toThrow(/at least 5/);
    expect(() => fitEos([10, 10, 11, 11, 12], [1, 1, 0, 0, 1])).toThrow(/distinct volumes/);
    expect(() => fitEos(volumes, energies.slice(1))).toThrow(/volumes but/);
  });

  it("rejects non-finite or non-positive input", () => {
    expect(() => fitEos([...volumes.slice(0, 5), -1], energies.slice(0, 6))).toThrow(/positive/);
    expect(() => fitEos(volumes, [NaN, ...energies.slice(1)])).toThrow(/not finite/);
    expect(() => fitEos(volumes, energies, { form: "sj" as EosName })).toThrow(/unknown/);
  });

  it("rejects a minimum outside the sampled range (expanded side; pymatgen also refuses)", () => {
    const data = ref.Cu_EMT_expanded_only;
    expect(data.pymatgen_error).toMatch(/not in the input volumes/);
    expect(() => fitEos(data.volumes, data.energies)).toThrow(/outside the sampled volumes/);
  });

  it("rejects a minimum outside the sampled range (compressed side; pymatgen extrapolates)", () => {
    const data = ref.Cu_EMT_compressed_only;
    expect(data.pymatgen_error).toBeNull();
    expect(() => fitEos(data.volumes, data.energies)).toThrow(/outside the sampled volumes/);
    // Opting in returns pymatgen's extrapolated fit, flagged with a warning.
    const fit = fitEos(data.volumes, data.energies, { requireBracketedMinimum: false });
    expect(fit.warnings.some((w) => /outside the sampled/.test(w))).toBe(true);
    expect(fit.v0 / data.pymatgen_v0! - 1).toBeLessThan(1e-5);
  });

  it("rejects non-convex garbage", () => {
    // Concave (a maximum, not a minimum).
    expect(() => fitEos([10, 11, 12, 13, 14], [0, 1, 1.5, 1, 0])).toThrow(/no minimum/);
    // Zig-zag noise with a downward trend.
    expect(() =>
      fitEos([10, 11, 12, 13, 14, 15], [0.3, -0.5, 0.1, -0.9, 0.2, -1.2]),
    ).toThrow(/no minimum|outside/);
  });

  it("warns about a poor fit to non-monotonic (zig-zag) data", () => {
    // A convex parabola plus ±0.3 eV alternating noise: fittable, but bad.
    const v = [10, 10.5, 11, 11.5, 12, 12.5, 13];
    const e = [1.425, 0.2, 0.425, -0.3, 0.425, 0.2, 1.425];
    const fit = fitEos(v, e);
    expect(fit.rSquared).toBeLessThan(0.99);
    expect(fit.warnings.some((w) => /poor/.test(w))).toBe(true);
  });
});
